const raw = $('Retell Tool Call').first().json.body || $('Retell Tool Call').first().json;
let body;
if (raw.arguments !== undefined) {
  body = typeof raw.arguments === 'string' ? JSON.parse(raw.arguments) : raw.arguments;
} else {
  body = raw;
}

const nombre = String(body.nombre || '').trim();
const telefono = String(body.telefono || '').trim();
const sede = String(body.sede || '').trim();
const servicio = String(body.servicio || '').trim();
const fecha = String(body.fecha || '').trim();
const hora = String(body.hora || '').trim();
const notas = String(body.notas || '').trim();
const empleadoInput = String(body.empleado || body.staff_member || '').trim();
const empleado = empleadoInput;

const TIEMPOS_EXPOSICION = {
  'Meches completas': { application: 45, exposure: 35, post: 10, total: 90 },
  'Meches tendencia': { application: 40, exposure: 40, post: 10, total: 90 },
  'Balayage': { application: 40, exposure: 40, post: 10, total: 90 },
  'Babylight': { application: 40, exposure: 40, post: 10, total: 90 },
  'Medias mechas': { application: 35, exposure: 35, post: 10, total: 80 },
  'Color Raíz': { application: 30, exposure: 25, post: 5, total: 60 },
  'Tinte raíz': { application: 30, exposure: 25, post: 5, total: 60 },
  'Baño de color orgánico': { application: 20, exposure: 35, post: 5, total: 60 },
  'Aplicación barros': { application: 40, exposure: 60, post: 10, total: 110 },
  'Tratamiento Keratina': { application: 40, exposure: 40, post: 10, total: 90 },
  'Tratamiento Antifrizz': { application: 60, exposure: 80, post: 20, total: 160 },
  'Alisado': { application: 60, exposure: 80, post: 20, total: 160 },
  'Permanente': { application: 40, exposure: 40, post: 10, total: 90 },
  'Desrizado frontal': { application: 20, exposure: 5, post: 5, total: 30 },
  'Tratamiento ligero intensivo': { application: 10, exposure: 5, post: 5, total: 20 },
  'Tratamiento premium': { application: 15, exposure: 10, post: 5, total: 30 },
  'Tratamiento slow repair': { application: 20, exposure: 20, post: 5, total: 45 },
  'Tratamiento détox cuero cabelludo': { application: 15, exposure: 10, post: 5, total: 30 },
  'Tratamiento détox mechas': { application: 15, exposure: 10, post: 5, total: 30 },
  'Tratamiento anticaída': { application: 10, exposure: 0, post: 5, total: 15 },
  'Manicura semipermanente': { application: 35, exposure: 5, post: 5, total: 45 },
  'Pedicura semipermanente': { application: 45, exposure: 10, post: 5, total: 60 },
  'Pedicura normal': { application: 40, exposure: 0, post: 5, total: 45 },
  'Tinte cejas': { application: 5, exposure: 3, post: 2, total: 10 },
  'Servicio Estrella': { application: 60, exposure: 45, post: 15, total: 120 }
};

const DURACIONES_SIMPLES = {
  'Corte Señora': 45, 'Corte Caballero': 30, 'Corte flequillo': 10,
  'Corte niño/a': 20, 'Lavado + Secado': 20, 'Peinado': 30,
  'Difusor': 15, 'Quitar humedad': 5, 'Cejas': 15,
  'Depilación axilas': 10, 'Depilación brazos': 20, 'Depilación ingles': 15,
  'Depilación ingles integral': 20, 'Depilación piernas': 30, 'Depilación espalda': 30,
  'Manicura normal': 30, 'Entrecejo': 10, 'Labio': 10
};

let applicationMin, exposureMin, postMin, totalMin;
const tiempos = TIEMPOS_EXPOSICION[servicio];
if (tiempos) {
  applicationMin = tiempos.application;
  exposureMin = tiempos.exposure;
  postMin = tiempos.post;
  totalMin = tiempos.total;
} else {
  applicationMin = DURACIONES_SIMPLES[servicio] || 60;
  exposureMin = 0;
  postMin = 0;
  totalMin = applicationMin;
}

const LOCATION_IDS = {
  'collado_villalba': '4159c713-3507-49ba-8319-c4b7ed4f38b2',
  'alpedrete': '61865f3b-976b-427b-b5f1-c856e7b97cdf'
};

const CALENDARIOS_EMPLEADOS = {
  'fernando': '06136cb5016a75da20e0292649097ca53d818c3145984831dda2d02311d929f4@group.calendar.google.com',
  'almudena': 'aade57f8bb3504fdc3582de697f8892c71817b94a2e32cebf8a891d8a1d48c2b@group.calendar.google.com',
  'johanna': 'c35d85ddf7afa97e4edb360ef99552b6289a2d95e9b939745bff7505557b73e2@group.calendar.google.com',
  'isabel': 'df5a40b3c772d155e8451db37483283cb815d71914dfd7af21750266da3eec48@group.calendar.google.com',
  'tania': '3e70700c207422d765f314fa80988edf99922c02bca81b62e0398347e15be65c@group.calendar.google.com',
  'macarena': '293331e0b723181277b20c87228b119f9701886dd1d3645a2747c7ee22b850e8@group.calendar.google.com',
  'alí': '01dabb00d1abb92b2313be55204645f2a6862e37f18779821045f3b1874250e1@group.calendar.google.com',
  'maria': '968ca744f4a0356d6948ae097d54127b373c9cc5efcc889479381101773ee8e7@group.calendar.google.com',
  'maria2': 'd70f48f63430635525a6ad0e7f835a32ae68a6e77aeb74810fd8ba9c4de836a2@group.calendar.google.com',
  'marian': '4cace839a6b98a4c7f5c910f4e898c1e0ebda5712c45939783b8e720543c9d5e@group.calendar.google.com',
  'ana': '7ced6d3e137d513c4cc58b517ad1fa344efbb883cdd3dbce8fd0046ac053c924@group.calendar.google.com',
  'cristina': '62b7d9a94d9f7a745d1d7c65448838ceecaa5ab4e999e3ace21546c913f7a710@group.calendar.google.com'
};

const fechaInicio = new Date(`${fecha}T${hora}:00`);
const fechaFin = new Date(fechaInicio.getTime() + totalMin * 60000);
const finApplication = new Date(fechaInicio.getTime() + applicationMin * 60000);
const inicioPost = new Date(finApplication.getTime() + exposureMin * 60000);

const diasSemana = ['domingo', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado'];
const meses = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];
const diaSemana = diasSemana[fechaInicio.getUTCDay()];
const diaMes = fechaInicio.getUTCDate();
const mes = meses[fechaInicio.getUTCMonth()];

const apellido = nombre.split(' ').pop();
const tituloEvento = `${nombre} - ${servicio} (${sede.replace('_', ' ')})${empleado ? ' con ' + empleado : ''}`;

const descripcion = `Cliente: ${nombre}\nTeléfono: ${telefono}\nServicio: ${servicio}\n\nTIEMPOS:\n- Inicio: ${hora}\n- Fin aplicación: ${finApplication.toISOString().split('T')[1].substring(0,5)}\n- Empleado libre: ${exposureMin} min\n- Vuelve empleado: ${inicioPost.toISOString().split('T')[1].substring(0,5)}\n- Fin cita: ${fechaFin.toISOString().split('T')[1].substring(0,5)}\n\nDuración total: ${totalMin} min\nTiempo activo empleado: ${applicationMin + postMin} min${empleado ? '\nEmpleada: ' + empleado : ''}${notas ? '\nNotas: ' + notas : ''}`;

const empleadoLower = empleado.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
let calendarId = 'primary';

if (empleado && CALENDARIOS_EMPLEADOS[empleadoLower]) {
  calendarId = CALENDARIOS_EMPLEADOS[empleadoLower];
} else if (empleado && empleado.length >= 2) {
  for (const [nombreNorm, calId] of Object.entries(CALENDARIOS_EMPLEADOS)) {
    if (nombreNorm.includes(empleadoLower) || empleadoLower.includes(nombreNorm)) {
      calendarId = calId;
      break;
    }
  }
}

return [{ json: {
  nombre,
  telefono,
  sede,
  servicio,
  fecha,
  hora,
  notas,
  empleado,
  applicationMin,
  exposureMin,
  postMin,
  totalMin,
  calendar_id: calendarId,
  location_id: LOCATION_IDS[sede],
  fechaInicio: fechaInicio.toISOString(),
  fechaFin: fechaFin.toISOString(),
  finApplication: finApplication.toISOString(),
  inicioPost: inicioPost.toISOString(),
  tituloEvento,
  descripcion,
  diaSemana,
  diaMes,
  mes,
  apellido
}}];

const gcalEvent = $('Google Calendar - Crear Evento').first().json;
const datos = $('Parsear Argumentos').first().json;

if (gcalEvent.id) {
  let mensajeConfirmacion = `Cita confirmada. Te esperamos el ${datos.diaSemana} ${datos.diaMes} de ${datos.mes} a las ${datos.hora} en ${datos.sede.replace('_', ' ')}`;

  if (datos.exposureMin > 0) {
    mensajeConfirmacion += `. La cita dura ${datos.totalMin} minutos, con tiempo de procesamiento incluido.`;
  }

  return [{
    json: {
      confirmado: true,
      id_cita: gcalEvent.id,
      google_calendar_id: gcalEvent.id,
      resumen: `${datos.nombre} - ${datos.servicio} el ${datos.diaSemana} ${datos.diaMes} de ${datos.mes} a las ${datos.hora}`,
      mensaje_confirmacion: mensajeConfirmacion,
      gcal_html_link: gcalEvent.htmlLink,
      empleado: datos.empleado,
      sede: datos.sede,
      tiempos: {
        application_min: datos.applicationMin,
        exposure_min: datos.exposureMin,
        post_min: datos.postMin,
        total_min: datos.totalMin,
        tiempo_activo_empleado: datos.applicationMin + datos.postMin
      }
    }
  }];
} else {
  return [{
    json: {
      confirmado: false,
      error: 'No se pudo crear el evento en Google Calendar',
      mensaje: 'Ha habido un problema al crear la cita. ¿Quieres que lo intentemos de nuevo?'
    }
  }];
}
